@ModuleInfo(name = "ComboOneHit", description = "Instantly kills people in the Combo gamemode", category = Category.COMBAT)
public final class ComboOneHit extends Module {

    public final NumberSetting packets = new NumberSetting("Packets", this, 50, 1, 1000, 25);

    @Override
    public void onAttackEvent(final AttackEvent event) {
        for (int i = 0; i < (int) packets.getValue(); i++) {
            PacketUtil.sendPacketWithoutEvent(new C02PacketUseEntity(event.getTarget(), C02PacketUseEntity.Action.ATTACK));
        }
    }
}


// NOTE (AI): The entire module is a rate-abuse loop: one AttackEvent triggers 50 to 1000 identical ATTACK packets, each sent with sendPacketWithoutEvent so the flood itself does not re-trigger attack listeners. It only works because vanilla 1.8.9 servers apply no per-tick attack cap; any anti-cheat that counts hits-per-second kills it instantly. The Combo gamemode this targets has no such check. Rise 6.1.30 and 6.2.4 ship the same module with PacketUtil.send, the 6.x equivalent of sendPacketWithoutEvent.

